def compute(vars):
    value = vars["v2"] - vars["v1"]
    return {
        "value": value,
        "trace": {
            "2015_payment": vars["v1"],
            "2016_payment": vars["v2"],
            "difference": value,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
